package com.sponsorcrm.controller;
import com.sponsorcrm.entity.*; import com.sponsorcrm.repository.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/benefits") @CrossOrigin(origins="http://localhost:5173") public class BenefitController { private final BenefitRepository repo; private final SponsorRepository sponsors; private final CampaignRepository campaigns; public BenefitController(BenefitRepository r,SponsorRepository s,CampaignRepository c){repo=r;sponsors=s;campaigns=c;}
 @GetMapping public List<Benefit> all(){return repo.findAll();} @PostMapping public Benefit create(@Valid @RequestBody Benefit b){b.setSponsor(sponsors.findById(b.getSponsor().getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Sponsor not found")));if(b.getCampaign()!=null&&b.getCampaign().getId()!=null)b.setCampaign(campaigns.findById(b.getCampaign().getId()).orElseThrow());return repo.save(b);}
 @PutMapping("/{id}") public Benefit update(@PathVariable Long id,@Valid @RequestBody Benefit b){Benefit x=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));x.setType(b.getType());x.setDescription(b.getDescription());x.setTargetValue(b.getTargetValue());x.setActualValue(b.getActualValue());x.setStatus(b.getStatus());x.setSponsor(sponsors.findById(b.getSponsor().getId()).orElseThrow());x.setCampaign(b.getCampaign()!=null&&b.getCampaign().getId()!=null?campaigns.findById(b.getCampaign().getId()).orElseThrow():null);return repo.save(x);}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.deleteById(id);}
}
